window.MONSTER_CHUNK_106 = [{"name":"Small Barracuda","cr":0.25,"xp":100,"alignment":"N","size":"Small","type":"animal","subtypes":["aquatic"],"init":3,"senses":[{"type":"low-light vision"}],"ac":14,"ac_touch":14,"ac_flat_footed":11,"ac_mods":"+3 Dex, +1 size","hp":4,"hd":"1d8","hdvalue":1,"fort":2,"ref":5,"will":1,"speed":[{"type":"swim","speed":70}],"melee":"bite +4 (1d4-1)","space":"5 ft.","reach":"5 ft.","strength":8,"dexterity":16,"constitution":11,"intelligence":1,"wisdom":12,"charisma":2,"baseatk":0,"cmb":-2,"cmd":11,"cmd_special":"can't be tripped","feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Perception","value":5},{"skill":"Swim","value":11}],"environments":["any aquatic"],"organizations":["pair","pack (2-5)","school (6-11)"],"treasure":"none","description_visual":"This fish is long and bluish gray fading to mottled silver near it tail. It has an oversized jaw full of sharp teeth.","group":"Barracuda","source":"Tome of Horrors Complete (3pp)","description":"The barracuda is a predatory fish that averages about two ft. long and weighs 10-15 pounds. Its body is bluish-gray near the front changing to silver mottled with black spots in the rear. Its mouth is filled with razor-sharp teeth. Medium barracudas are about six ft. long and weigh 30-45 pounds. Large barracudas are about ten ft. long and weigh 50-80 pounds.\n\nThe barracuda strikes quickly in combat. Slain prey is devoured immediately.","ecology":"","habitat_society":""},{"name":"Spire Monkey","cr":0.25,"xp":100,"alignment":"N","size":"Tiny","type":"animal","init":2,"senses":[{"type":"low-light vision"}],"ac":14,"ac_touch":14,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 size","hp":4,"hd":"1d8","hdvalue":1,"fort":2,"ref":4,"will":1,"speed":[{"type":"land","speed":30},{"type":"climb","speed":30}],"melee":"2 claws +4 (1d3-1) and bite -1 (1d3-1)","space":"2-1/2 ft.","reach":"0 ft.","strength":8,"dexterity":15,"constitution":10,"intelligence":2,"wisdom":12,"charisma":5,"baseatk":0,"cmb":-3,"cmd":9,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Climb","value":10},{"skill":"Perception","value":5}],"environments":["warm jungles"],"organizations":["solitary","pair","clan (3-14)"],"treasure":"none","description_visual":"The Spire Monkey is a two-headed, six-armed monkey that lives on roofs (spires and minarets are preferred) and high in the treetops. In some tropical countries they are tolerated in cities as messengers of the gods, and roam temples with impunity.","group":"Monkey","source":"Tome of Horrors 4 (3pp)","description":"Omnivorous and foul-tempered, spire monkeys race from rooftop to rooftop and steal food (and occasionally loose coins or trinkets) from the streets below. Spire monkeys attack by clawing, as well as by throwing rocks or other small objects (such as roof tiles), and can divide their attacks between two opponents. They can climb as fast as they can run, and leap from tree to tree or building to building.","ecology":"","habitat_society":"","credit":"Original author Scott Wylie Roberts, \"Myrystyr\"; Pathfinder conversion by Skeeter Green  Originally appearing in Jungle Ruins of Madaro-Shanti (© Frog God Games, 2010)"},{"name":"Tiny Monstrous Sea Wasp","cr":0.25,"xp":100,"alignment":"N","size":"Tiny","type":"vermin","subtypes":["aquatic"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"watersense","modifier":"60 ft."}],"ac":13,"ac_touch":11,"ac_flat_footed":12,"ac_mods":"+1 Dex, +2 size","hp":4,"hd":"1d8","hdvalue":1,"fort":3,"ref":1,"will":3,"defensive_abilities":["transparent"],"immunities":["vermin traits"],"speed":[{"type":"swim","speed":30}],"melee":"tentacle +3 (1d3-5 plus poison)","space":"2-1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"entangle"}],"strength":5,"dexterity":13,"constitution":10,"wisdom":10,"charisma":2,"baseatk":0,"cmb":31,"cmd":41,"cmd_special":"can't be tripped","feats":[{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Escape Artist","value":11},{"skill":"Perception","value":4},{"skill":"Stealth","value":19},{"skill":"Swim","value":9}],"sq":[{"type":"jet"},{"type":"transparent"}],"environments":["warm aquatic"],"organizations":["solitary","ring (2-5)"],"treasure":"incidental","description_visual":"A translucent blue and nearly invisible in water, this cube-shaped jellyfish has four distinct sides and trails dozens of extremely long tentacles.","group":"Sea Wasp","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Entangle","kind":"Ex","details":"A sea wasp can entangle a creature up to two sizes smaller than itself with its tentacles with a successful CMB check. An entangled opponent suffers tentacle damage and the effect of its poison each round the hold is maintained. An entangled creature still receives a save to avoid the effects of its poison. While a foe is entangled, the sea wasp cannot attack any other creature."},{"type":"Poison","kind":"Ex","details":"Sting-injury; the effects of the poison are determined by the creature's size. The DC of the save is Constitution-based. Size Fort DC Frequency Effect Cure Tiny 10 1/round for 1d4 rounds 1 Con 1 save Small 11 1/round for 1d4 rounds 1d2 Con 1 save Medium 11 1/round for 1d6 rounds 1d3 Con 1 save Large 13 1/round for 1d6 rounds 1d4 Con 2 consecutive saves Huge 15 1/round for 1d6 rounds 1d6 Con 2 consecutive saves Gargantuan 20 1/round for 1d6 rounds 1d8 Con 3 consecutive saves"},{"type":"Jet","kind":"Ex","details":"A monstrous sea wasp can jet backward once per round as a full-round action at a speed equal to four times its swim speed. It must move in a straight line, but doesn't provoke attacks of opportunity while jetting."},{"type":"Transparent","kind":"Ex","details":"A monstrous sea wasp is nearly invisible floating in the water. An observer must make a successful DC 20 Perception check to notice the sea wasp."},{"type":"Watersense","kind":"Ex","details":"Monstrous sea wasps can automatically sense the location of anything within 60 ft. that is in contact with water."}],"description":"Monstrous sea wasps are deadly aquatic creatures with long, writhing and highly poisonous tentacles that extend for several yards. They inhabit warm waters and tend to congregate near coastal regions or river mouths where they wait for prey to wash downstream to them. Monstrous sea wasps are also called box jellyfish or marine stingers. Almost invisible in the water, the sea wasp has four eyes, one on each side of the bell, connected to a nerve ring inside the main body. They have no brain, but are able to process visual information. These eyes are invisible to all but the keenest observers. Monstrous sea wasps feed on a variety of marine life including fish, manta rays and stingrays, and crustaceans. The larger monstrous sea wasps also feed on sharks, whales, giant fish, giant squids, octopi, and swimmers. Prey that becomes entangled in its mass of tentacles is quickly stung by the sea wasp and then coiled into its mouth and devoured. Monstrous sea wasps are non-aggressive and don't actively hunt for food. They simply float along in the water waiting for a living creature to swim into its mass of tentacles. When it detects prey in its tentacles, it folds them around the prey, and stings it. A monstrous sea wasp's poison (particularly the larger ones) is meant to instantly kill its prey so it doesn't struggle and damage the sea wasp's delicate form. Sages catalogue the sea wasp's sting as being one of the deadliest and most painful one can experience. A creature stung by a sea wasp that lives to tell about, never forgets its brush with this monstrosity.","ecology":"","habitat_society":""},{"name":"Black Orc","cr":0.3333,"xp":135,"race":"Black orc","classes":[{"class":"warrior","level":1}],"alignment":"CE","size":"Medium","type":"humanoid","subtypes":["orc"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":11,"ac_flat_footed":16,"ac_mods":"+5 armor, +1 Dex, +1 natural","hp":8,"hd":"1d10+3","hdvalue":1,"fort":4,"ref":1,"will":-1,"save_mods":"+4 vs. undead attacks","defensive_abilities":["blessing of Orcus","ferocity"],"dr":"1/-","speed":[{"type":"land","speed":20}],"melee":"longspear +5 (1d8+6/x3)","ranged":"light crossbow +2 (1d8, 19-20/x2)","space":"5 ft.","reach":"5 ft.","strength":19,"dexterity":12,"constitution":14,"intelligence":9,"wisdom":8,"charisma":6,"baseatk":1,"cmb":5,"cmd":16,"feats":[{"feat":"Power Attack"}],"skills":[{"skill":"Intimidate","value":2}],"languages":["Common","Orc"],"environments":["temperate hills","temperate mountains"],"organizations":["gang (2-4)","squad (11-20 plus 2 3rd-level sergeants and 1 leader of 3rd-6th level)","band (30-300 plus 150% noncombatant plus 1 3rd-level sergeant per 10 adults, 5 5th-level lieutenants, and 3 7th-level captains)","tribe (1d4 bands plus 1 10th-12th level chieftain)"],"treasure":"standard","description_visual":"This creature resembles a 7-foot tall orc with bluish-black skin and red eyes.","group":"Orc","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Blessing of Orcus","kind":"Su","details":"Black orcs gain a +4 racial bonus on all saving throws made to resist any attack or effect created by an undead creature."}],"description":"Fully a head taller than an ordinary orc these foul brutes have been known to make other orcs cringe in fear. Unlike normal orcs, black orcs move in daylight as well as they do the darkness of their subterranean lairs (they don't have the light sensitivity penalty that normal orcs have). Black orcs were taken in early ages by Orcus the Demon Lord of Undead and bred with demonic blood in a matter that would accommodate his diabolical needs. Black orcs refer to their dark master as \"Old Man Death\". These orcs fairly worship death and display the death's head prominently upon their standards and devices. They are often found in the service of necromancers and move easily in mixed groups of zombies, skeletons, and even ghouls. Larger and more intelligent than their lesser kin, black orcs look down on other orc races as inferior to themselves. When forced to cooperate with other orc tribes in large forces black orcs consistently plot to overthrow the other tribe's chieftain and take command. This treachery is likely the reason there are so few bands of the black orc nation known to exist, as the infighting tends to keep their numbers down. Black orcs stand 7 ft. tall and weigh 200 to 280 pounds. Females tend to be about the same height, but are a bit lighter. Both males and females have blue-black skin with red eyes and more pronounced tusks than their smaller cousins. Black orcs have a decent understanding of tactics. They are adept in the use of reach weapons such as longspears and glaives. Many of their number are proficient in the use of light crossbows. In melee they prefer to gang up on powerful opponents and dispatch them quickly before moving on to lesser foes whenever possible. As they are often led by clerics and necromancers in the service of Orcus, they are likely to take prisoners if possible with the intent of sacrificing them to the Demon Lord of Undead at some future time.","as_character":[{"description":"Black orc leaders tend to be clerics or barbarians. Black orc clerics worship Orcus. A black orc cleric has access to two of the following domains: Chaos, Death, Destruction, Evil, and War. Black orc clerics favor spells that deal damage or create undead.","racial_traits":[{"type":"Ability Score Bonuses","value":"+8 Strength, +2 Dexterity, +4 Constitution, -2 Intelligence, -2 Wisdom, -4 Charisma: Black orcs are brutal and savage."},{"type":"Darkvision","value":"Black orcs can see in the dark up to 60 ft."},{"type":"AC","value":"+1 natural armor bonus."},{"type":"Blessing of Orcus","value":"Ferocity DR 1/- Light Sensitivity"},{"type":"Weapon Familiarity","value":"Black orcs are always proficient with greataxes and falchions, and treat any weapon with the word \"orc\" in its name as a martial weapon."},{"type":"Languages","value":"Black orcs begin play speaking Common and Orc. Black Orcs with high Intelligence scores can choose from the following languages: Abyssal, Dwarven, Giant, Gnoll, Goblin, Undercommon."}]}],"ecology":"","habitat_society":"","gear":"scale mail, longspear, light crossbow, 10 bolts"},{"name":"Blood Orc","cr":0.3333,"xp":135,"race":"Blood orc","classes":[{"class":"warrior","level":1}],"alignment":"CE","size":"Medium","type":"humanoid","subtypes":["orc"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":15,"ac_touch":11,"ac_flat_footed":14,"ac_mods":"+4 armor, +1 Dex","hp":8,"hd":"1d10+3","hdvalue":1,"fort":4,"ref":2,"will":-2,"defensive_abilities":["ferocity"],"weaknesses":["light sensitivity"],"speed":[{"type":"land","speed":30}],"melee":"greataxe +5 (1d12+6/x3), bite +0 (1d4+2)","ranged":"javelin +2 (1d6+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"frenzy"}],"strength":18,"dexterity":13,"constitution":14,"intelligence":8,"wisdom":6,"charisma":6,"baseatk":1,"cmb":5,"cmd":16,"feats":[{"feat":"Power Attack"}],"skills":[{"skill":"Intimidate","value":2}],"languages":["Common","Orc"],"environments":["temperate hills"],"organizations":["gang (2-4)","squad (11-20 plus 2 3rd-level sergeants and 1 leader of 3rd-6th level)","band (30-300 plus 150% noncombatant plus 1 3rd-level sergeant per 10 adults, 5 5th-level lieutenants, and 3 7th-level captains)","tribe (1d4 bands plus 1 10th-12th level chieftain)"],"treasure":"standard","description_visual":"This massive creature resembles a powerful orc with bestial jaws and oversized tusks. It wears black armor and carries a wicked greataxe caked in blood. Its armor and hair, like its weapon, is caked with dried blood.","group":"Orc","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Frenzy","kind":"Ex","details":"Once per day a blood orc who smells or tastes blood during combat may fly into a frenzy in the following round, biting and attacking with its weapons until it or its opponent is dead. It gains +2 Strength, +2 Constitution, and -2 AC. The creature cannot end its frenzy voluntarily."}],"description":"Blood orcs are considered vicious killers even amongst other breeds of orcs. Distrusted in times of peace, their savage warriors are sought out in times of war for their brutality and ferocity. Blood orc bands decorate their standards and shields with the scalps and severed heads of opponents and are known to drink flagons of putrid blood before entering battle. Blood orcs always fight to the death, take few prisoners, and offer no quarter to their foes. Blood orcs have a special hatred for black orcs whom they see as traitors to the orcish god Grotaag. A typical male blood orc stands over 6 ft. tall and weighs around 200 pounds or more. Females tend to be slightly lighter and smaller. Blood orcs skin is dark reddish-black and their hair is black, dark brown, or crimson (rare, but it does occur). Eye color is always black. Blood orcs favor armor and clothes of black or dark red. Skilled in combat, blood orcs are ruthless opponents, attacking with weapons and savage bite. They swarm foes and are known for assaulting the center of enemy forces, overbearing defenders with their brutal attacks. Their most common tactic is to form a shield wall with heavy wooden shields. The front rows of attackers break enemy lines with battleaxes while the rear ranks attack with longspears and glaives. Once melee is mixed and blood is in the air, the blood orcs drop both in favor of greataxes. When faced with magic-using opponents they spread themselves out to avoid being consumed by area of effect spells. Blood Orc Society Blood orcs are a primitive (even for orcs), barbaric race of people. Hunters and nomads by nature, they rarely settle in one place for long being always on the move following any source of food. Blood orc tribes and villages tend to congregate near one another for protection, food, and various other needs. Most tribes or villages also situate themselves near an abundant source of water. Other orc tribes avoid the blood orc nations, seeing them as savages and primitives. Trade between the blood orcs and other races is rare though blood orcs do tend to favor the company of gnolls, flinds, and hobgoblins (why, no one knows). Each tribe or village is let by an elder warrior, a barbarian of great strength and power. Each tribe also includes at least a single shaman or witch doctor who tends to the wounded, predicts the future, and so on.","as_character":[{"description":"Blood orc leaders tend to be barbarians. Blood orcs pay homage to Grotaag. Clerics have access to two of the following domains: Chaotic, Evil, Trickery, and War.","racial_traits":[{"type":"Ability Score Bonuses","value":"+8 Strength, +2 Dexterity, +4 Constitution, -2 Intelligence, -4 Wisdom, -4 Charisma. Blood orcs are brutal and savage."},{"type":"Darkvision","value":"Blood orcs can see in the dark up to 60 ft."},{"type":"Scent","value":"Blood orcs can detect enemies and other creatures by scent."},{"type":"Ferocity Light Sensitivity Natural Weapons","value":"Blood orcs can make a bite (1d4) as a secondary attack."},{"type":"Special Attacks","value":"Frenzy."},{"type":"Languages","value":"Blood orcs begin play speaking Common and Orc. Blood orcs with high Intelligence scores can choose from the following languages: Giant, Goblin."}]}],"ecology":"","habitat_society":"","gear":"chain shirt, greataxe, 3 javelins"},{"name":"Conshee","cr":0.3333,"xp":135,"alignment":"CN","size":"Tiny","type":"fey","init":2,"senses":[{"type":"detect evil"},{"type":"detect good"},{"type":"low-light vision"}],"ac":16,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+2 Dex, +2 natural, +2 size","hp":3,"hd":"1d6","hdvalue":1,"fort":0,"ref":4,"will":3,"dr":"4/cold iron","speed":[{"type":"land","speed":30},{"type":"fly","speed":50,"maneuverability":"perfect"}],"melee":"dagger +0 (1d2-2)","ranged":"short bow +4 (1d3-2)","space":"2-1/2 ft.","reach":"0 ft.","spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect evil"},{"spell":"detect good"}]},{"frequency":"1/day","spells":[{"spell":"fear"},{"spell":"silence"},{"spell":"warp wood"}]},{"frequency":"2/day","spells":[{"spell":"blink"},{"spell":"entangle"},{"spell":"invisibility"},{"spell":"levitate"}]},{"frequency":"3/day","spells":[{"spell":"faerie fire"},{"spell":"light"},{"spell":"silent image"}]}],"strength":6,"dexterity":15,"constitution":11,"intelligence":12,"wisdom":13,"charisma":13,"baseatk":0,"cmb":0,"cmd":12,"feats":[{"feat":"Alertness"}],"skills":[{"skill":"Bluff","value":5},{"skill":"Diplomacy","value":5},{"skill":"Escape Artist","value":6},{"skill":"Fly","value":18},{"skill":"Perception","value":7},{"skill":"Sleight of Hand","value":6},{"skill":"Stealth","value":14}],"languages":["Common","Sylvan"],"environments":["any underground"],"organizations":["troop (3-6)","band (7-12)","swarm (13-22)"],"treasure":"standard (dagger, shortbow with 20 arrows)","description_visual":"This creature appears to be a tiny, hairless, gray-skinned humanoid with leathery wings, small horns, and bulbous crimson eyes.","source":"Tome of Horrors 4 (3pp)","description":"Conshee make their homes in large, open subterranean caverns far from the surface world. They spend most of their days mining, collecting minerals, or simply enjoying the natural beauty of their surroundings. Conshee don't take intrusions lightly and are moved to anger quickly when their homes are threatened. The conshee have an intense dislike for mites and generally attack them on sight. Captured mites are killed almost immediately; very rarely are they ever taken prisoner. Mites seem to dislike the conshee equally as much, though captured conshee are often kept as slaves or sold back to their conshee clan or family.\n\nConshee prefer ambush tactics to straight-forward combat, attacking at range with their short bows and spell-like abilities. Some conshee also use daggers, saps, and other such weapons, allowing them to attack quickly and often times unnoticed. Conshee also employ a wide array of traps, snares, and pitfalls to injure, confuse, or capture would-be opponents. The corridors and passages leading to a conshee lair are often rife with all manner of such traps and pitfalls. Conshee often employ natural poisons as well, taken from the various plants, leaves, and underground flowers near their lairs.\n\nAn adult conshee stands about 2 ft. tall. It is a small lithe creature with grayish skin, a hairless body, and two leathery bat-like wings growing from its back. Its hands end in claws, though they are not strong enough to use in combat.","ecology":"","habitat_society":""},{"name":"Floating Eye","cr":0.3333,"xp":135,"alignment":"N","size":"Diminutive","type":"magical beast","subtypes":["aquatic"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":16,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+2 Dex, +4 size","hp":5,"hd":"1d10","hdvalue":1,"fort":2,"ref":4,"will":-3,"speed":[{"type":"swim","speed":60}],"melee":"bite +0 (1d2-5)","space":"1 ft.","reach":"0 ft.","special_attacks":[{"type":"hypnotic gaze","details":"DC 10, 1d6+1 rounds"}],"strength":1,"dexterity":15,"constitution":11,"intelligence":1,"wisdom":4,"charisma":2,"baseatk":1,"cmb":-8,"cmd":4,"feats":[{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":4},{"skill":"Stealth","value":14,"special":"+22 to hide"},{"skill":"Swim","value":10}],"environments":["any aquatic"],"organizations":["school (3-12)"],"treasure":"none","description_visual":"This creature looks like a 6-inch long semi-transparent fish with a single large eye located in the center of its body along its dorsal region.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Hypnotic Gaze","kind":"Ex","details":"Creatures meeting the gaze of a floating eye must succeed on a DC 10 Will save or stand and stare blankly at the floating eye (similar to the effects of a hypnotism spell) for 1d6+1 rounds. A swimming creature that fails its save doesn't sink, but floats on the surface of the water. The save DC is Constitution-based."}],"description":"Floating eyes are small saltwater fish that have transparent bodies and a single large eye about the size of a walnut located in the center of their body. Floating eyes are most often found underground in forgotten dungeon waterways and underground lakes and seas. The creature's eye is capable of bioluminescence, and it has such minute control over the intensity and patterns of the light that it can mesmerize other creatures that see it. Floating eyes are part of an unusual symbiotic relationship with a variety of predatory fish, including sharks. Once the floating eye has mesmerized its prey, predatory fish move in and consume it. After they have eaten, the floating eye moves in and gorges itself on the scraps.\n\nFloating eyes avoid combat, relying on their hypnotic gaze ability. If forced into combat, they bite an opponent.","ecology":"","habitat_society":"","credit":"The Floating Eye originally appeared in the First Edition Monster Manual (© TSR/Wizards of the Coast, 1977) and is used by permission."},{"name":"Fox","cr":0.3333,"xp":135,"alignment":"N","size":"Small","type":"animal","init":3,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":14,"ac_flat_footed":12,"ac_mods":"+3 Dex, +1 natural, +1 size","hp":4,"hd":"1d8","hdvalue":1,"fort":2,"ref":5,"will":1,"speed":[{"type":"land","speed":40}],"melee":"bite +4 (1d4-1)","space":"5 ft.","reach":"5 ft.","strength":8,"dexterity":17,"constitution":10,"intelligence":2,"wisdom":12,"charisma":6,"baseatk":0,"cmb":-2,"cmd":11,"cmd_special":"+4 vs. trip","feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":5},{"skill":"Perception","value":5},{"skill":"Stealth","value":15},{"skill":"Survival","value":5}],"environments":["cold forests","cold plains","temperate forests","temperate plains"],"organizations":["solitary"],"treasure":"none","description_visual":"The small, red-furred creature has an inquisitive face and large ears. It slinks silently through the brush as it stalks its prey.","source":"Tome of Horrors Complete (3pp)","description":"Foxes are opportunistic eaters with a diet that consists of mice and voles, rabbits, birds, eggs, amphibians and small reptiles, fish, mollusks, earthworms, carrion, and plants. Foxes are also known to scour garbage and refuse in settled areas. The statistics above describe the common red fox, but can be used for other foxes such as the grey fox or arctic fox. Arctic foxes gain an additional +4 racial bonus on Stealth checks in snowy surroundings.\n\nThe fox is a very territorial creature and spends about one-third of its day hunting for food (most hunting is performed at night). Foxes are excellent hunters and have even been known to bring down prey much larger than themselves. When prey is encountered, the fox leaps at it and dispatches it with a series of quick bites.","ecology":"","habitat_society":""},{"name":"Ghost-faced Orc","cr":0.3333,"xp":135,"race":"Ghost-faced orc","classes":[{"class":"warrior","level":1}],"alignment":"CE","size":"Medium","type":"humanoid","subtypes":["orc"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":13,"ac_touch":10,"ac_flat_footed":13,"ac_mods":"+3 armor","hp":7,"hd":"1d10+1 (+1)","hdvalue":1,"fort":3,"ref":0,"will":0,"defensive_abilities":["ferocity","invisible in shadows"],"weaknesses":["light sensitivity"],"speed":[{"type":"land","speed":30}],"melee":"greataxe +4 (1d12+4/x3)","ranged":"shortbow +1 (1d6/x3)","space":"5 ft.","reach":"5 ft.","strength":17,"dexterity":10,"constitution":12,"intelligence":7,"wisdom":10,"charisma":5,"baseatk":1,"cmb":4,"cmd":14,"feats":[{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Stealth","value":3}],"languages":["Common","Orc"],"environments":["temperate hills","temperate mountains"],"organizations":["gang (2-4)","squad (11-20 plus 2 3rd-level sergeants and 1 leader of 3rd-6th level)","band (30-300 plus 150% noncombatant plus 1 3rd-level sergeant per 10 adults, 5 5th-level lieutenants, and 3 7th-level captains)"],"treasure":"standard","description_visual":"This creature looks like an orc whose face and head is painted in a grotesque skull-like pattern.","group":"Orc","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Invisible in Shadows","kind":"Ex","details":"When a ghost-faced orc stands still or moves slowly (no more than 5 ft. per round) in shadowy illumination or complete darkness, it becomes effectively invisible to all natural and extraordinary sight, including darkvision and other sight-based senses. A ghost-faced orc invisible in shadows can still be detected by hearing and smell. A true seeing spell (or other similar magic) reveals its location as well."}],"description":"When they may be seen at all, ghost-faced orcs appear as normal orcs who paint their faces in grotesque skull like patterns. Invisible in shadow and darkness to all but one another due to unholy pacts with their dark god, their face paint gives them the impression of floating disembodied skulls. Ghost-faced orcs are similar in every way to their common cousins—filthy, smelly, aggressive and thoroughly cruel. Their hair is ranges from black to slate grey to shock white. Their equipment is ill kempt and crudely made, leaving most to forage for better gear amongst their victims. Ghostfaces are seldom seen above ground except on moonless nights. Ghost-faced orcs are proficient with all simple weapons. Most are warriors, fighters or barbarians and favor greataxes and longspears to any other weapon. They on occasion carry shortbows for hunting or ambushes. Ghost-Faced Orc Society Ghost-faced orcs differ little from their kin with the exception that a larger portion of their population are clerics in service of Grotaag. As such these battle priests hold a revered place in society. The priesthood is referred to as the Ghost Face Cabal which is made up of the highest level clerics amongst the tribe. The cabals outfit themselves and their most powerful slayers with enchanted weapons, armor and potions.","as_character":[{"description":"Ghost-faced Orc leaders tend to be clerics of Grotaag or powerful barbarian champions. Clerics have access to two of the following domains: Chaotic, Evil, Trickery, and War.","racial_traits":[{"type":"Ability Score Bonuses","value":"+6 Strength, +2 Constitution, -4 Intelligence, -6 Charisma. Ghost-faced orcs are brutal and savage."},{"type":"Darkvision","value":"Ghost-faced orcs can see in the dark up to 60 ft."},{"type":"Special Qualities","value":"ferocity, invisible in shadows, light sensitivity"},{"type":"Languages","value":"Ghost-faced orcs begin play speaking Common and Orc. Ghost-faced orcs with high Intelligence scores can choose from the following languages: Giant, Goblin."}]}],"ecology":"","habitat_society":"","gear":"studded leather armor, greataxe, shortbow, 20 arrows"},{"name":"Greenskin Orc","cr":0.3333,"xp":135,"race":"Greenskin orc","classes":[{"class":"warrior","level":1}],"alignment":"CE","size":"Medium","type":"humanoid","subtypes":["orc"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":14,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+2 armor, +2 Dex","hp":7,"hd":"1d10+1 (+1)","hdvalue":1,"fort":3,"ref":2,"will":-1,"defensive_abilities":["ferocity"],"weaknesses":["light sensitivity"],"speed":[{"type":"land","speed":30}],"melee":"longsword +3 (1d8+2/19-20)","ranged":"composite longbow (+2 Str) +3 (1d8+2/x3)","space":"5 ft.","reach":"5 ft.","strength":15,"dexterity":15,"constitution":12,"intelligence":7,"wisdom":8,"charisma":6,"baseatk":1,"cmb":3,"cmd":15,"feats":[{"feat":"Point Blank Shot"}],"skills":[{"skill":"Perception","value":2},{"skill":"Stealth","value":2,"special":"+6 in temperate and warm forests"}],"languages":["Common","Orc"],"environments":["temperate forests","warm forests"],"organizations":["gang (2-4)","squad (11-20 plus 2 3rd-level sergeants and 1 leader of 3rd-6th level)","band (30-300 plus 150% noncombatant plus 1 3rd-level sergeant per 10 adults, 5 5th-level lieutenants, and 3 7th-level captains)"],"treasure":"standard","description_visual":"This creature looks like an ugly orc with green slime colored skin, small tusks, and canine-like eyes.","group":"Orc","source":"Tome of Horrors Complete (3pp)","description":"Wiry and quick, these slime green orcs have long ears, smallish tusks, and coyote like eyes. They shoot first and eat later. Greenskins are a wicked orcish species of arboreal hunters. More stealthy and agile than their common cousins they are slighter of build but suffer no penalties from daylight or bright light. They are generally open and friendly to other evil humanoid races and often set up trade routes with said creatures. They make their homes among the dense foliage of the forest building their wooden huts from the trees and branches. Some tribes even build their entire village among the treetops (as a defense measure against land-based adversaries). Greenskin orcs stand about 6 ft. tall. Females are slightly smaller. Hair color is always black or greenish-black. Eye color varies, but is usually dark brown, dark green, or occasionally deep, rich blue. Greenskins are highly proficient in the use stealth and surprise, attacking with their ranged weapons when an enemy is sighted. They seek to disable and weaken foes with arrows before closing to finish the job with their wicked longswords. Greenskin Orc Society Greenskins tend to get along well with most other species of orcs being smart enough to take orders and wise enough to keep their mouths shut. They often serve roles in mixed tribes as scouts and skirmishers. Greenskins are mortal enemies of elves and the bane of fey and enchanted woodland creatures. They torture such beings mercilessly should they manage to take one alive. Despite their skill with the longbow, greenskin warriors are equally proficient with the longsword and hunting knife. Greenskins tend to hunt in packs, using their scent ability to track their quarry. Their hunting packs are competitive with one another, each member seeking to be the one to make the kill. Greenskins are likely to have 1d2 trained worgs among them. Greenskin lairs often have as many as two dozen of these foul creatures living and sleeping amongst their masters filthy sleeping rags. Greenskin tribes are known to hire themselves out to civilized masters as scouts and even irregular and regular missile units. They are also likely to serve evil druids and despotic ranger lords.","as_character":[{"description":"Greenskin leaders tend to be rangers or druids. Greenskin orcs pay homage to \"He of the One Eye\" or a nature god local to the area. A greenskin orc cleric has access to two of the following domains: Evil, Strength, and War.","racial_traits":[{"type":"Ability Score Bonuses","value":"+4 Strength, +4 Dexterity, +2 Constitution, -4 Intelligence, -2 Wisdom, -4 Charisma."},{"type":"Darkvision","value":"Greenskin orcs can see in the dark up to 60 ft."},{"type":"Special Qualities","value":"ferocity, light sensitivity, scent"},{"type":"Keen Senses","value":"Greenskin orcs gain a +2 racial bonus to Perception checks."},{"type":"Camouflage","value":"Because of their coloration, greenskin orcs gain a +4 racial bonus to Stealth checks when in temperate and warm forests."},{"type":"Languages","value":"Greenskin orcs begin play speaking Common and Orc. Greenskin orcs with high Intelligence scores can choose from the following languages: Giant, Goblin."}]}],"ecology":"","habitat_society":"","gear":"leather armor, longsword, composite longbow (+2 Str), 20 arrows"},{"name":"Grippli","cr":0.3333,"xp":135,"race":"Grippli","classes":[{"class":"warrior","level":1}],"alignment":"N","size":"Small","type":"humanoid","subtypes":["grippli"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":14,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+1 Dex, +1 dodge, +1 natural, +1 size","hp":7,"hd":"1d10+1 (+1)","hdvalue":1,"fort":3,"ref":1,"will":1,"speed":[{"type":"land","speed":30},{"type":"climb","speed":30}],"melee":"short sword +2 (1d4/19-20)","ranged":"dart +3 (1d3) or net +3 (entangle)","space":"5 ft.","reach":"5 ft.","strength":11,"dexterity":13,"constitution":12,"intelligence":12,"wisdom":11,"charisma":6,"baseatk":1,"cmb":1,"cmd":14,"feats":[{"feat":"Dodge"}],"skills":[{"skill":"Climb","value":12},{"skill":"Perception","value":4},{"skill":"Stealth","value":5,"special":"+11 to hide in marshes or forests"},{"skill":"Swim","value":4}],"languages":["Common","Grippli"],"sq":[{"type":"swamp stride"}],"environments":["warm forests","warm marshes"],"organizations":["solitary","gang (2-5)","pack (6-11)","village (20-30 plus 35% noncombatants plus 1 3rd-level cleric)"],"treasure":"standard","description_visual":"This creature looks like a bipedal tree frog, smaller than a halfling, and with humanoid arms and hands in place of its forelimbs. Its skin is grayish-green with dark green swirls and stripes.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Swamp Stride","kind":"Ex","details":"Gripplis can move across marshlands, swamps, and mud without any penalty to their movement speed."}],"description":"Gripplis are short frog-like humanoids that dwell in swamps and marshes. They can move upright or on all fours. They spend most of their time scooting about their community doing many of the same tasks that humans employ in their own communities. A grippli stands 2 to 2-1/2 ft. tall and weighs from 40 to 50 pounds. Its eyes are yellow with vertical-slit pupils of black. Gripplis often wear brightly colored or decorated clothes. They are attracted to and love brightly colored items. Gripplis are peaceful and nonaggressive, only attacking when threatened or frightened. They prefer to keep their opponents at distance and attack using their nets and darts. If engaged in melee, gripplis employ short swords. Some gripplis coat their darts with poison before entering battle. A grippli village is human-like in organization. Each grippli family maintains its own dwelling place. The huts are small and constructed of wood and mud. Gripplis build them beneath the branches of large trees so as to shade themselves from the long, hot days. Each grippli village is led by a tribal leader (usually a female adept or cleric of at least 3rd level). Gripplis survive through trade with other peace-loving races such as elves and halflings or through hunting. Gripplis are fond of various fruits and insects (including the giant varieties) and collect and store them in village huts for the winter months when food becomes scarce. Gripplis reproduce by laying eggs. A typical clutch contains a single egg, as gripplis are slow to reproduce. For this reason, they defend their young with a ferocity unknown among many other races.","as_character":[{"description":"Grippli leaders are usually rogues or rogue/fighters. Grippli priests are usually adepts. Grippli clerics have access to two of the following domains: Animal, Plant, Protection, and Travel. Grippli characters possess the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"-2 Strength, +2 Dexterity, +2 Intelligence, +2 Wisdom, -2 Charisma: Gripplis are agile, clever, and taciturn."},{"type":"Small Size","value":"Gripplis are Small creatures and gain a +1 size bonus to their AC, a +1 size bonus on attack rolls, a -1 penalty to their CMB and CMD, and a +4 size bonus on Stealth checks."},{"type":"Fast","value":"Gripplis are fast for their size, and have a base speed of 30 ft. Gripplis have a base climb speed is 30 ft."},{"type":"Darkvision","value":"Gripplis can see in the dark up to 60 ft."},{"type":"Defensive Camouflage","value":"Gripplis have a +6 bonus on Stealth checks to hide in marshes or forests."},{"type":"Special Qualities","value":"Swamp stride."},{"type":"Automatic Languages","value":"Grippli."},{"type":"Bonus Languages","value":"Common, Sylvan, Elven, Goblin, Orc."}]}],"ecology":"","habitat_society":"","credit":"The Grippli originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission.","gear":"short sword, 6 darts, net"},{"name":"Kuah-lij","cr":0.3333,"xp":135,"race":"Kuah-lij","classes":[{"class":"warrior","level":1}],"alignment":"LN","size":"Medium","type":"humanoid","subtypes":["kuah-lij"],"init":1,"senses":[{"type":"low-light vision"}],"ac":11,"ac_touch":11,"ac_flat_footed":10,"ac_mods":"+1 Dex","hp":7,"hd":"1d10+2","hdvalue":1,"fort":4,"ref":1,"will":1,"speed":[{"type":"land","speed":30}],"melee":"dagger +0 (1d4-1/19-20)","ranged":"light crossbow +2 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","strength":8,"dexterity":13,"constitution":14,"intelligence":17,"wisdom":13,"charisma":8,"baseatk":1,"cmb":0,"cmd":10,"feats":[{"feat":"Master Craftsman (any craft)"},{"feat":"Skill Focus (any craft)"}],"skills":[{"skill":"Craft (any one)","value":14},{"skill":"Knowledge (arcana)","value":7},{"skill":"Knowledge (any two)","value":7},{"skill":"Perception","value":2},{"skill":"Swim","value":3}],"languages":["Aquan","Common","Elven","Gnome","Kuah-Lij"],"sq":[{"type":"gifted craftsman"},{"type":"magic item use"}],"environments":["any land"],"organizations":["company (2-4)","squad (11-20 plus 1 leader of 3rd-6th level and 2 3rd-level lieutenants)","band (30-50 plus 1 3rd-level sergeant per 10 adults, 2 5th-level lieutenants, and 1 7th-level captain)"],"treasure":"standard","description_visual":"This creature resembles a gnome that has been stretched vertically to a height of a human. Its features are knobby and elongated. Its hair is light and downy, more akin to a soft fur than anything else, and its skin is white with pale blue undertones.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Gifted Craftsmen","kind":"Ex","details":"Due to their skill at crafting items of all kinds, kuah-lij gain Master Craftsman as a bonus feat even if they don't have the normal prerequisites. In addition, kuah-lij only pay 75% of the total gp cost when creating magic items if they have access to a kuah-lij production facility. Magic Item Use (EX) Kuah-lij can use magic items as if they have 1 level of wizard. This innate ability doesn't increase with level unless the kuah-lij gains levels in the wizard class."}],"description":"The kuah-lij are a race of humanoids that inhabit a distant world orbiting a great red sun. They are lawful and organized, but a dying people due to a series of disasters on their home world, and now search for aid. For several millennia, the kuah-lij lived in relative peace on an old world in an advanced civilization, though much of the technology was magic-based. This changed with a series of plagues that devastated the population, followed by a gradual, inexplicable advancement of the size of their oceans. Huge floods resulted. These cataclysms were followed by the invasion of a ferocious aquatic race resembling the aboleths. The aboleth-like creatures lurked in the deepest ocean trenches of the kuah-lij planet, and attacked by coming up from the depths. The kuah-lij, accomplished artisans, retaliated by building a series of magically enhanced sea craft to travel the deeps and attack these beings. Thus far they have arrived at a stalemate, and the kuah-lij now seek aid from other worlds and planes in their battle against their deepwater adversaries. Individual kuah-lij commoners rely upon their military and combat specialists to protect them. With their focus on magical technology, they have easy access to a great many magical devices which they can use to defend themselves with as well. The Kuah-lij were at one time a peaceful race of explorers, living in an organized society on a distant planet orbiting a great red sun. Though the course of their lives was regimented, their culture allowed them scope for individuality, and in fact encouraged it. This, and the natural propensity of the kuah-lij for order, resulted in a society that had remained fresh and vigorous for over 10,000 years. Kuah-lij young are placed into a public crèche to be raised within days of birth, to be raised by child care specialists. As they grow and are educated, their affinities and talents are assessed, and at age 15 they are assigned a vocation, based on their talents, and an avocation, based on their preferences. They then study more intensely in these two areas, until they reach maturity at age 25. Kuah-lij youths have the option of changing vocation or avocation if they insist upon it, though this almost never occurs. Upon reaching maturity, they fully enter society, where they spend 10 months of the year working at their vocation 10 hours per day, and the final two months on sabbatical, traveling, exploring, or doing whatever else strikes them as interesting. Their culture is based on a complex system of credit, with currency reserved only for dealing with non-kuahlij, and medicine, vacation time, and other services are all socialized, but due to their innately organized, cooperative mindset, there is remarkably little corruption within their culture. The kuah-lij had civilized their planet millennia ago, and had settlements across its lands and beneath its seas. Many areas they deliberately kept undeveloped, and they took great pleasure in long sea voyages and extended exploration of back country. Their innate tendency to organized society also helped them immeasurably with mass production and technology, in particular a merging of science and magic. Though it never reached the pinnacles seen in other exotic cross-planar cultures, it was highly polished, with many of their technological marvels being as much works of art as useful items. This idyllic existence came to an end over 300 years ago, when a strange darkness crept into the deepest places of their oceans. Kuah-lij explorers that investigated did not return, or came back reporting nothing amiss-but with a strange gleam in their eyes. They merged back into the kuah-lij culture, and immediately set about sabotaging it, destroying it from within. Despite their placid lives, the kuah-lij had many thousands of years of history to draw upon, and were able to take this in stride. Yet even as they isolated the tainted members of their society and set about investigating the cause of this in detail, the invaders of the deeps began to strike, poisoning food supplies, then attacking Kuah-lij undersea cities, often overwhelming them without warning or survivors. As the years passed, the kuah-lij culture became more militant, fighting a war against a race they had almost no information about. The battle has entered a kind of stalemate: the Kuah-lij have many sea-based vessels and devices to use against their foes, but the enemies of the deep, which resemble aboleths, are surmised to have secret aid from an extraplanar source, and also apparently limitless numbers. The kuah-lij have turned some of their efforts to exploring distant worlds, in this plane and beyond, for answers to the origins of their attackers, and how to deal with them. This is their single, overriding concern.","as_character":[{"description":"Kuah-lij are defined by their class levels-they don't possess racial Hit Dice. All kuah-lij possess the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Intelligence, -4 Charisma"},{"type":"Base Speed","value":"A kuah-lij's base land speed is 30 ft."},{"type":"Low-light Vision","value":"Kuah-lij can see twice as far as humans in conditions of dim light. ."},{"type":"Racial Skills","value":"Kuah-lij receive a +2 bonus on all Craft skill checks."},{"type":"Racial Feats","value":"Due to their skill at crafting items of all kinds, kuah-lij gain Master Craftsman as a bonus feat even if they don't have the normal prerequisites."},{"type":"Languages","value":"Kuah-lij begin plays speaking Common and Kuah-lij. Kuah-lij with high Intelligence scores can choose from the following bonus languages: Aquan, Elven, and Gnome."}]}],"ecology":"","habitat_society":"","credit":"The Kuah-Lij can be found in the Necromancer Games module Dead Man's Chest. ©2005 Bill Webb and Clark Peterson, Necromancer Games, Inc.).","gear":"dagger, light crossbow, 20 crossbow bolts"},{"name":"Podokesaurus","cr":0.3333,"xp":135,"alignment":"N","size":"Tiny","type":"animal","init":8,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":17,"ac_touch":16,"ac_flat_footed":13,"ac_mods":"+4 Dex, +1 natural, +2 size","hp":6,"hd":"1d8+2","hdvalue":1,"fort":4,"ref":6,"will":4,"save_mods":"Will: +2 vs. fear","speed":[{"type":"land","speed":60}],"melee":"bite +1 (1d3-1), 2 claws +1 (1d2-1)","space":"1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"pounce"}],"strength":8,"dexterity":19,"constitution":14,"intelligence":2,"wisdom":11,"charisma":5,"baseatk":0,"cmb":13,"cmd":24,"feats":[{"feat":"Improved Initiative"},{"feat":"Run","type":"bonus"}],"skills":[{"skill":"Perception","value":4}],"environments":["warm forests"],"organizations":["gang (5-12)","pack (13-24)"],"treasure":"none","description_visual":"This small bipedal reptile has a long, narrow head and sharp, curved teeth.","group":"Dinosaur","source":"Tome of Horrors 4 (3pp)","description":"Podokesaurus are small, swift-footed pack hunters that feast on a diet of meat, often attacking prey much larger than themselves. In such instances, they use their overwhelming numbers to bring their quarry down.\n\nAn adult podokesaurus stands about 1 foot tall and is around 3 ft. long. Its long tail acts as a counterweight to keep it upright when it is running at a high rate of speed. Skin color varies slightly, but is usually varying shades of browns and grays. Its teeth are curved and serrated to aid in tearing meat for consumption.\n\nA lone podokesaurus isn't much of a threat, especially to larger opponents. In large numbers however, these creatures become extremely dangerous, using pack and swarming tactics to attack. Prey that attempts to escape is easily run down by the swarming podokesaurus.","ecology":"","habitat_society":""},{"name":"Silid","cr":0.3333,"xp":135,"race":"Silid","classes":[{"class":"warrior","level":1}],"alignment":"CE","size":"Small","type":"humanoid","subtypes":["goblinoid"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+2 armor, +2 Dex, +1 size","hp":8,"hd":"1d10+2 (+1)","hdvalue":1,"fort":4,"ref":2,"will":-1,"weaknesses":["light blindness"],"speed":[{"type":"land","speed":30}],"melee":"short sword +4 (1d6+1)","ranged":"shortspear +4 (1d4+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"}],"spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":3,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"blur"}]}],"strength":13,"dexterity":15,"constitution":14,"intelligence":10,"wisdom":9,"charisma":4,"baseatk":1,"cmb":1,"cmd":13,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Perception","value":0},{"skill":"Stealth","value":11}],"languages":["Goblin","Undercommon"],"environments":["any underground"],"organizations":["gang (5-10)","band (11-16, plus 1 3rd-level leader)","stripe (21-40 plus 50% noncombatants plus 1 3rdlevel sergeant, 1 lieutenant of 4th level, and 1 leader of 6th or 7th level)"],"treasure":"standard","description_visual":"A small goblin-like humanoid emerges from the shadows. It is dressed in drab garments which match its pale gray, leathery skin. An unkempt shock of short black hair frames its bat-like face, slightly pointed ears and bulbous red pupils and its long and slender arms end in four-fingered hands.","source":"Tome of Horrors Complete (3pp)","description":"These small subterranean dwellers enjoy ambushing and waylaying their opponents. They slay their victims, steal their possessions, and leave their bodies to what ever happens to wander along looking for a meal. Cruel, mean-spirited creatures, silids care nothing for themselves or anything else. They seem to take great pleasure in bringing misery to others, particularly adventurers. Silids rarely interact with other races. They are an untrustworthy lot, and most other races avoid contact with them. Silids live in groups (called stripes) of up to 40 individuals. Each stripe is a loose organization of silids, with a single leader that controls and governs the remainder of the stripe. The leader is almost always the meanest, cruelest, and sneakiest silid of the bunch. Under his command, the silids conduct raids and hunt their subterranean realm for surface dwellers that have wandered into their territory. When hunting or harassing travelers, silids often don armor (either leather or padded) and carry weapons. Silids skulk about their underground world in search of surface dwellers. Surface-dwellers seem to love exploring the Underdark, so there rarely is a shortage of opponents for the mean-spirited silid. Often, a band of silids trails an adventuring party before attacking; waiting until the terrain is just right (silids prefer small, cramped areas because they gain the advantage on larger opponents). When the attack commences, a silid blurs itself and usually employs one of the following tactics. The silids attack from ambush, attempting to maim or kill as many of their opponents as they can. Or, the silids rush from all angles and swarm their opponents. The latter tactic is usually only used when a large group of silids are present (such as when a party of adventurers stumbles into a silid lair).","as_character":[{"description":"Silids are defined by their class levels-they don't possess racial Hit Dice. All silids have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+4 Dexterity, +2 Constitution, -4 Charisma. Silids are lithe, acrobatic and furtive stalkers."},{"type":"Small","value":"Silids are Small creatures and gain a +1 size bonus to their AC, a +1 size bonus on attack rolls, a -1 penalty to their CMB and CMD, and a +4 size bonus on Stealth checks."},{"type":"Fast","value":"Silids are fast for their size, and have a base speed of 30 ft."},{"type":"Darkvision","value":"Silids can see in the dark up to 60 ft."},{"type":"Weaknesses","value":"A silid's eyes are sensitive eyes to daylight and have the Light Blindness weakness."},{"type":"Spell-like abilities","value":"A silid can cast blur once per day with a caster level equal to its hit dice. This ability is Wisdom-based."},{"type":"Skilled","value":"+4 racial bonus on Stealth checks."},{"type":"Languages","value":"Silids begin play speaking Goblin and can also speak Undercommon if they have an Intelligence of at least 10. Silids with high Intelligence can choose from the following languages: Orc, Sylvan."}]}],"ecology":"","habitat_society":"","gear":"leather armor, short sword, spear"},{"name":"Wizard's Shackle","cr":0.3333,"xp":135,"alignment":"N","size":"Diminutive","type":"magical beast","init":0,"senses":[{"type":"arcanesense","modifier":"30 ft."},{"type":"blindsight","modifier":"10 ft."}],"ac":14,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+4 size","hp":5,"hd":"1d10","hdvalue":1,"fort":2,"ref":0,"will":0,"defensive_abilities":["sealed mind"],"speed":[{"type":"land","speed":5}],"melee":"bite +5 (1d2-5 plus attach)","space":"1 ft.","reach":"0 ft.","special_attacks":[{"type":"spell drain"}],"strength":1,"dexterity":10,"constitution":11,"intelligence":1,"wisdom":11,"charisma":2,"baseatk":1,"cmb":-3,"cmb_special":"+20 vs. grapple when attached","cmd":2,"cmd_special":"+20 vs. grapple when attached","feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Perception","value":4}],"environments":["any"],"organizations":["colony (2-5)","swarm (6-11)"],"treasure":"none","description_visual":"This tiny creature appears to be a gray-green leech.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Arcanesense","kind":"Su","details":"A wizard's shackle can automatically detect the location of any arcane spellcaster within 30 ft. This functions in a similar fashion to a detect evil spell but there is no chance the wizard's shackle is stunned and it isn't blocked by stone, lead, or other material."},{"type":"Attach","kind":"Ex","details":"If a wizard's shackle hits with a bite attack, it latches onto the opponent's body. An attached wizard's shackle is effectively grappling its prey. The wizard's shackle loses its Dexterity bonus to AC and has an AC of 14, but holds on with great tenacity. Wizard's shackles have a +20 racial bonus on grapple checks (already figured into the CMB and CMD entries above). An attached wizard's shackle can be struck with a weapon or grappled itself. To remove an attached wizard's shackle through grappling, the opponent must achieve a pin against the wizard's shackle."},{"type":"Spell Drain","kind":"Su","details":"A wizard's shackle drains spells when attached to an arcane spellcaster. Each round the wizard's shackle remains attached, it drains 1d6 levels of prepared spells or unused slots, beginning with the highest level spell or slot available. For example, on a roll of 4 against a 5th-level wizard, a wizard's shackle drains four levels of prepared spells. The wizard currently has one 3rd-level spell, two 2nd-level spells, and three 1st-level spells prepared. The wizard's shackle drains the 3rd-level spell and one of the 1st-level spells (determined randomly). A creature drained of spells or slots can attempt a DC 12 Intelligence check with a +2 bonus to notice that something is wrong (though unless he searches his body, he might still overlook the wizard's shackle). Once a wizard's shackle has drained at least 4 spell levels, it detaches and crawls away to digest its meal. Lost spells or slots can be regained normally."}],"description":"The wizard's shackle is a 6-inch long, leech-like creature. Though it is small in size, it is greatly feared by spellcasters, for its bite drains arcane magic from a caster's mind. In some rare instances, evil spellcasters have harvested these monsters and set them loose in an enemy spellcaster's tower or laboratory. A wizard's shackle attacks from ambush. It favors hiding on ledges, bookshelves, doors, and other such places where it can drop on spellcasters that pass underneath it. A wizard's shackle injects an anesthetic when it bites, so it is possible that its bite goes unnoticed (DC 12 Perception check to notice).","ecology":"","habitat_society":""},{"name":"Albino Cave Spider","cr":0.5,"xp":200,"alignment":"N","size":"Tiny","type":"vermin","init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":17,"ac_touch":16,"ac_flat_footed":13,"ac_mods":"+4 Dex, +1 natural, +2 size","hp":4,"hd":"1d8","hdvalue":1,"fort":2,"ref":4,"will":7,"immunities":["vermin traits"],"speed":[{"type":"land","speed":20},{"type":"climb","speed":10}],"melee":"bite +6 (1d3-3 plus poison)","space":"2-1/2 ft.","reach":"2-1/2 ft.","strength":4,"dexterity":18,"constitution":10,"wisdom":10,"charisma":3,"baseatk":0,"cmb":16,"cmb_special":"+4 vs. grapple","cmd":28,"feats":[{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Acrobatics","value":4,"special":"+12 jump"},{"skill":"Climb","value":12},{"skill":"Stealth","value":16}],"environments":["any underground"],"organizations":["solitary","nest (2-20)"],"treasure":"standard","description_visual":"This tiny hunting spider is about the size of a man's fist. It is pallid white, often with irregular light brown blotches on its abdomen, which helps it blend in with the toadstools and fungus which is its home. The albino cave spider normally feeds on normal and dire rats, but it attacks anything that comes within range.","group":"Spider","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save DC 14 Fort; frequency 1/round for 4 rounds; effect 1d2 Constitution damage; cure 1 save. The save DC is Constitution-based and includes a +4 racial bonus."}],"description":"Albino cave spiders hunt rats in caves or in deep underground regions where the sun never reaches. These tiny killers are extremely sensitive to movement, and despite their unique coloring, are highly adept at hiding and stealthy stalking.\n\nThe albino cave spider is mildly toxic, as some of the other Under Realm predators have discovered. They use their poisonous bite to sicken prey and follow until they can feast on the remains.\n\nMale and female cave spiders are roughly the same size, with females being slightly larger. The females are the predominant hunters, with the males tending to the web-nest when an eggsack is present. Both sexes are extremely protective of the eggsack, and attack larger foes when it is threatened.","ecology":"","habitat_society":""},{"name":"Carbuncle","cr":0.5,"xp":200,"alignment":"N","size":"Small","type":"aberration","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+2 insight, +3 natural, +1 size","hp":8,"hd":"1d8+1 (+3)","hdvalue":1,"fort":1,"ref":2,"will":3,"defensive_abilities":["foresight"],"speed":[{"type":"land","speed":10}],"melee":"bite +1 (1d3 -2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"discord"}],"strength":7,"dexterity":10,"constitution":12,"intelligence":10,"wisdom":18,"charisma":8,"baseatk":0,"cmb":-2,"cmd":5,"cmd_special":"+4 vs. trip","feats":[{"feat":"Toughness"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Escape Artist","value":4},{"skill":"Knowledge (any)","value":4},{"skill":"Perception","value":8},{"skill":"Stealth","value":8}],"languages":["telepathy 100 ft."],"environments":["temperate forests"],"organizations":["solitary"],"treasure":"none (forehead gem worth 500 gp)","description_visual":"This creature resembles a cross between an anteater and armadillo.  Embedded in its head is a large red jewel. The creature has a long snout and a low-slung body protected by several thick leathery bands. Its hide is dappled gray and brown, shading to lighter colors of gray on its underbelly.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Discord","kind":"Su","details":"As a standard action, a carbuncle can sow discord in a creature within 30 ft. using its telepathy ability. It can use this ability once per round to affect one creature. An affected creature must succeed on a DC 14 Will save or fall into loud bickering and arguing with those around him. Meaningful communication is impossible. If the affected creatures have different alignments, there is a 50% chance that they attack each other. Bickering lasts 5d4 rounds. Fighting begins 1d4 rounds into the bickering and lasts 2d4 rounds. This is a mind-affecting effect. The save DC is Wisdom-based."},{"type":"Foresight","kind":"Su","details":"A carbuncle has a +2 insight bonus to AC and Reflex saves. This ability is always active and cannot be negated or dispelled."}],"description":"Deep in the tangled underbrush of forests and in the remote regions of dismal swamps and bogs lives a strange creature called the carbuncle. The carbuncle is a withdrawn creature and seeks to avoid encounters. Should it seek interaction, a carbuncle often begins by proudly announcing the value of the gem in its forehead just to watch the reaction such information arouses.\n\nDespite its overall shy nature, the carbuncle has a mischievous side as well, often seeking to join travelers in order to play pranks and gauge the reactions of the unfortunate victims of its curiosity. After joining with a party, a carbuncle will seek to cause discord by using selective telepathic images and prophesies to breed hostility and suspicion between party members. It will often telepathically contact nearby monsters and lead them to attack the party so that it can watch in fascination and read the thoughts of the party as they are attacked, slipping away at an opportune moment.\n\nA carbuncle can be coerced to surrender the gem in its forehead. This requires a successful DC 20 Bluff check. If successful, the carbuncle releases the gem. If the check fails, the carbuncle sees through the deception and attempts to flee. When a carbuncle is slain, its forehead gem crumbles to dust. If the carbuncle relinquishes its gem, it grows another one within one month.\n\nThough fascinated by combat, carbuncles are nearly helpless in melee.\n\nThey much prefer to set up encounters using their powers and then watch the brutal scenes unfold. Carbuncles surrender immediately if attacked. If placed under duress, a carbuncle wills itself to die. A favorite tactic of the carbuncle is befriending a party and accompanying them on their quest.\n\nOnce it has achieved this objective, it uses its discord ability to cause suspicion, hostility, and disruption among the party members.","ecology":"","habitat_society":"","credit":"The Carbuncle originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Cave Cricket","cr":0.5,"xp":200,"alignment":"N","size":"Small","type":"vermin","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":11,"ac_flat_footed":15,"ac_mods":"+4 natural, +1 size","hp":5,"hd":"1d8+1","hdvalue":1,"fort":3,"ref":0,"will":0,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":30}],"melee":"2 kicks +2 (1d3+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"chirp"}],"strength":13,"dexterity":10,"constitution":12,"wisdom":10,"charisma":7,"baseatk":0,"cmb":0,"cmd":10,"cmd_special":"+8 vs. trip","skills":[{"skill":"Acrobatics","value":0,"special":"+10 when jumping"},{"skill":"Perception","value":2}],"sq":[{"type":"leap"}],"environments":["any underground"],"organizations":["solitary","cluster (2-5)"],"treasure":"none","description_visual":"This creature appears to be a giant cricket, about the size of a dog. Its body is pale gray in color.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Chirp","kind":"Ex","details":"Creatures within 20 ft. of a chirping cave cricket cannot be heard unless they scream. Spellcasters in the area must succeed on a DC 11 Concentration check to successfully cast a spell. The chirping increases the chance of wandering monsters by 30%. The check DC is Constitution-based."},{"type":"Leap","kind":"Ex","details":"A cave cricket is a natural leaper and gains a +10 racial bonus to Acrobatics checks when jumping."}],"description":"Cave crickets are larger versions of normal crickets and, much like the smaller crickets they resemble, are relatively harmless. The cave cricket's chirping can be heard to a range of 300 ft. Cave crickets are about 3 ft. long.\n\nCave crickets are mostly harmless, noisy insects and rarely attack living creatures. If attacked, a cave cricket uses its powerful legs to kick its opponents before hopping away.","ecology":"","habitat_society":"","credit":"The Cave Cricket originally appeared in the First Edition module S4 The Lost Caverns of Tsojcanth (© TSR/Wizards of the Coast, 1982) and later in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Clockwork Scout","cr":0.5,"xp":200,"alignment":"N","size":"Tiny","type":"construct","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":16,"ac_touch":15,"ac_flat_footed":13,"ac_mods":"+3 Dex, +1 natural, +2 size","hp":5,"hd":"1d10","hdvalue":1,"fort":0,"ref":3,"will":1,"immunities":["construct traits"],"speed":[{"type":"land","speed":40}],"melee":"slam +1 (1d6-2)","space":"2-1/2 ft.","reach":"0 ft.","strength":6,"dexterity":17,"wisdom":12,"charisma":10,"baseatk":1,"cmb":2,"cmd":10,"skills":[{"skill":"Perception","value":3}],"sq":[{"type":"animal appearance"}],"environments":["any"],"organizations":["solitary","squad (2-8)"],"treasure":"none","description_visual":"A rat watches you motionlessly from its dead black eyes. Small spasms seem to vibrate beneath portions of its skin from time to time.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Animal Appearance","kind":"Ex","details":"Clockwork scouts are constructed to resemble small animals such as badgers, dogs, or cats. Often, their inner wood and metal workings are covered by an animal's pelt, while their frame is specially constructed to help reinforce the illusion that they are an animal. A character must succeed on a DC 15 Knowledge (nature), Perception or Survival check to notice that the scout isn't an actual animal."}],"description":"Scouts are constructed to resemble animals commonly found in the area that the brain gear operates within. This camouflage helps them move about unnoticed and gives them the opportunity to strike from ambush.\n\nClockwork scouts are designed to serve as the mobile eyes and ears of a clockwork colony. While still restricted by the 2-mile radius they must remain within to keep contact with a brain gear, scouts serve an important role as reconnaissance, patrol, and pursuit troops.\n\nClockwork scouts prefer to attack from ambush. Often, they climb trees and leap down upon opponents. If they come across an enemy camp, the brain gear may direct them to sneak into the camp and steal equipment or carry off water, food, and other necessities. Usually, the brain gear prefers to hold scouts back from combat. Only if the scouts have a chance to strike from a devastating ambush does the brain gear order them into battle.","ecology":"","habitat_society":""},{"name":"Euparkeria","cr":0.5,"xp":200,"alignment":"N","size":"Small","type":"animal","init":2,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":14,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+2 Dex, +1 natural, +1 size","hp":13,"hd":"2d8+4","hdvalue":2,"fort":7,"ref":5,"will":1,"speed":[{"type":"land","speed":40}],"melee":"bite +3 (1d4+1), 2 claws (1d3+1)","space":"5 ft.","reach":"5 ft.","strength":12,"dexterity":15,"constitution":14,"intelligence":2,"wisdom":12,"charisma":8,"baseatk":1,"cmb":1,"cmd":13,"feats":[{"feat":"Great Fortitude"}],"skills":[{"skill":"Perception","value":10}],"environments":["any land"],"organizations":["gang (2-4)","pack (5-12)"],"treasure":"none","description_visual":"This grayish-green reptile is about the size of a small dog. Its snout is long and its mouth is filled with needle-like teeth.","group":"Dinosaur","source":"Tome of Horrors 4 (3pp)","description":"Euparkeria is a nocturnal carnivore, feeding on insects and small game. When moving, it usually moves on all fours; however, when running or in combat, it stands and fights on its back legs.\n\nA euparkeria can reach lengths of 3 ft. or more. Skin coloration is gray or grayish-green.\n\nWhen attacking prey, the euparkeria stands on its hind legs and attacks with a vicious bite. Its front legs feature a small thumb-like claw that it uses to slash its opponents. Much like other small dinosaurs, by itself the euparkeria doesn't pose much of a threat. In large numbers however, they can easily catch and kill prey much larger than themselves.","ecology":"","habitat_society":""}];
